import { test, expect } from '@playwright/test';

test.describe('Login Page Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    // Navigate to login page
    await page.goto('https://example.com/login');
  });

  test('should display login form elements correctly on mobile', async ({ page }) => {
    // Verify login heading is visible
    const heading = page.getByRole('heading', { name: /login/i });
    await expect(heading).toBeVisible();

    // Verify email input field is visible and properly sized
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
    const emailBox = await emailInput.boundingBox();
    expect(emailBox?.width).toBeGreaterThan(300);

    // Verify password input field is visible and properly sized
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();
    const passwordBox = await passwordInput.boundingBox();
    expect(passwordBox?.width).toBeGreaterThan(300);

    // Verify login button is visible and clickable
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();
    await expect(loginButton).toBeEnabled();
  });

  test('should have proper spacing and layout on mobile viewport', async ({ page }) => {
    // Verify no horizontal scrollbar is needed
    const bodyWidth = await page.evaluate(() => document.body.scrollWidth);
    const viewportWidth = await page.evaluate(() => window.innerWidth);
    expect(bodyWidth).toBeLessThanOrEqual(viewportWidth);

    // Verify form container is properly centered
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify all interactive elements are touch-friendly (minimum 44x44 pixels)
    const emailInput = page.getByLabel(/email/i);
    const emailBox = await emailInput.boundingBox();
    expect(emailBox?.height).toBeGreaterThanOrEqual(44);

    const passwordInput = page.getByLabel(/password/i);
    const passwordBox = await passwordInput.boundingBox();
    expect(passwordBox?.height).toBeGreaterThanOrEqual(44);

    const loginButton = page.getByRole('button', { name: /login/i });
    const buttonBox = await loginButton.boundingBox();
    expect(buttonBox?.height).toBeGreaterThanOrEqual(44);
  });

  test('should display forgot password and signup links on mobile', async ({ page }) => {
    // Verify forgot password link is visible
    const forgotPasswordLink = page.getByRole('link', { name: /forgot password/i });
    await expect(forgotPasswordLink).toBeVisible();

    // Verify signup link is visible
    const signupLink = page.getByRole('link', { name: /sign up|register/i });
    await expect(signupLink).toBeVisible();

    // Verify links are properly spaced for mobile interaction
    const forgotBox = await forgotPasswordLink.boundingBox();
    expect(forgotBox?.height).toBeGreaterThanOrEqual(40);
  });

  test('should handle text input on mobile without zoom', async ({ page }) => {
    // Verify input fields have proper font size to prevent auto-zoom
    const emailInput = page.getByLabel(/email/i);
    const fontSize = await emailInput.evaluate((el) => {
      return window.getComputedStyle(el).fontSize;
    });

    // Font size should be at least 16px to prevent auto-zoom on iOS
    const fontSizeValue = parseInt(fontSize);
    expect(fontSizeValue).toBeGreaterThanOrEqual(16);

    // Verify password input also has proper font size
    const passwordInput = page.getByLabel(/password/i);
    const passwordFontSize = await passwordInput.evaluate((el) => {
      return window.getComputedStyle(el).fontSize;
    });

    const passwordFontSizeValue = parseInt(passwordFontSize);
    expect(passwordFontSizeValue).toBeGreaterThanOrEqual(16);
  });
});
